using System.Reflection;
using System.Windows;
using System.Windows.Automation;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using YoWidgets;
internal static class VoiceCallUiChecks
{
    const BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
    static T Field<T>(object target,string name)=>(T)target.GetType().GetField(name,Hidden)!.GetValue(target)!;
    static void Click(Button button)=>button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
    static void Require(bool result,string message)=>LiveVoiceChecks.Require(result,message);
    internal static void Run()
    {
        var root=Path.GetFullPath("artifacts/live-voice-ui/run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var app=new App{ShutdownMode=ShutdownMode.OnExplicitShutdown};typeof(App).GetProperty(nameof(App.DataRoot))!.SetValue(null,root);Ui.Theme();var manager=new WidgetManager(root,true);typeof(App).GetProperty(nameof(App.Manager))!.SetValue(app,manager);
        manager.Settings.AiProvider="Gemini";manager.Settings.AiModel="gemini-flash-lite-latest";manager.Settings.AiKeyProtected=AiService.Protect("fixture-key");manager.Save();Exception? failure=null;
        var widget=new WidgetWindow(manager,new WidgetState{Kind="assistant",Enabled=true,Size="M",X=240,Y=160},true);
        app.Startup+=async(_,_)=>{try{
            var abandoned=new VoiceActionBridge(manager);typeof(VoiceActionBridge).GetField("ownedRequest",Hidden)!.SetValue(abandoned,manager.Data.Ai.SessionVersion);manager.Data.Ai.NewChat();typeof(AiService).GetProperty(nameof(AiService.Busy))!.SetValue(manager.Data.Ai,true);abandoned.Dispose();Require(manager.Data.Ai.Busy,"Ending an old call cancelled a newer chat request");manager.Data.Ai.Cancel();
            widget.Show();await Task.Delay(220);var view=All<AssistantView>(widget).Single();var send=Field<Button>(view,"send");var input=Field<TextBox>(view,"input");
            Require(send.IsEnabled&&AutomationProperties.GetName(send)=="Start call","Empty composer did not offer Start call");Snapshot(widget,Path.Combine(root,"empty-composer.png"));
            input.Text="a";await Task.Delay(50);Require(AutomationProperties.GetName(send)=="Send message","First letter did not restore Send");input.Clear();manager.Data.Ai.DraftAttachments.Add(AssistantAttachment.FromBytes("note.txt",[65]));typeof(AssistantView).GetMethod("Refresh",Hidden)!.Invoke(view,null);Require(AutomationProperties.GetName(send)=="Send message","File attachment did not restore Send");manager.Data.Ai.DraftAttachments.Clear();typeof(AssistantView).GetMethod("Refresh",Hidden)!.Invoke(view,null);
            Console.WriteLine("PASS voice UI: empty draft shows Start call; text and attachment restore Send");
            LiveVoiceChecks.Audio? audio=null;LiveVoiceChecks.Socket? socket=null;LiveVoiceSession? session=null;
            view.VoiceSessionFactory=(p,m,v,k,c)=>{audio=new();socket=new();return session=new(p,m,v,k,c,socket,audio);};
            Click(send);await Task.Delay(420);Require(audio?.Recording==true,"Start call did not start live session");var call=Field<VoiceCallView>(view,"callView");Require(Field<Border>(view,"composer").Visibility==Visibility.Collapsed&&call.ActualHeight>250,"Voice panel did not replace the composer");var orb=Field<CallOrb>(call,"orb");Require(orb.Active&&orb.IsAnimating,"Live orb animation not running");
            socket!.Emit("{\"serverContent\":{\"inputTranscription\":{\"text\":\"Hello there\"},\"outputTranscription\":{\"text\":\"Hello. How can I help?\"}}}");await Task.Delay(100);var callHint=All<TextBlock>(call).Single(t=>t.Text=="AI voice · Uses your chat API key");var hintBottom=callHint.TranslatePoint(new Point(0,callHint.ActualHeight),view).Y;Require(hintBottom<view.ActualHeight-5,"Call footer is clipped at the bottom");Snapshot(widget,Path.Combine(root,"live-call.png"));
            socket.Emit(System.Text.Json.JsonSerializer.Serialize(new{toolCall=new{functionCalls=new[]{new{id="calendar-voice",name="widget_command",args=new{action="calendar_add",arguments_json=System.Text.Json.JsonSerializer.Serialize(new{title="Voice fixture task",due=DateTimeOffset.Now.AddDays(1).ToString("O")})}}}}}));await LiveVoiceChecks.Until(()=>manager.Settings.CalendarTasks.Count==1&&session!.ActionLog.Count==1);await LiveVoiceChecks.Until(()=>socket.Snapshot().Any(s=>s.Contains("functionResponses")&&s.Contains("saved")));Console.WriteLine("PASS voice UI actions: live function call reaches shared widget dispatcher, saves calendar task and returns verified result");
            Click(Field<Button>(call,"mute"));Require(session!.Muted&&!audio!.Recording,"Mute button did not stop actual capture adapter");Click(Field<Button>(call,"mute"));Require(!session.Muted&&audio!.Recording,"Unmute button failed");
            Click(Field<Button>(call,"voices"));await Task.Delay(300);var popup=Field<Popup>(call,"picker");Snapshot((FrameworkElement)popup.Child,Path.Combine(root,"voices.png"));var leda=All<Button>(popup.Child).First(b=>(string?)b.ToolTip=="Use Leda");Click(leda);await Task.Delay(250);Require(manager.Settings.VoiceCall.GeminiVoice=="Leda"&&!session.Active&&!audio!.Recording,"Voice selection did not end call/save preference");Console.WriteLine("PASS voice UI: live panel/orb, Mute and animated voice chooser with saved selection");
            Click(Field<Button>(call,"reconnect"));await Task.Delay(150);Require(session!.Connected&&audio!.Recording,"New voice could not reconnect");
            var source=PresentationSource.FromVisual(call)!;var escape=new KeyEventArgs(Keyboard.PrimaryDevice,source,Environment.TickCount,Key.Escape){RoutedEvent=Keyboard.PreviewKeyDownEvent};call.RaiseEvent(escape);await Task.Delay(250);Require(escape.Handled&&!session!.Active&&audio!.Disposed&&Field<VoiceCallView?>(view,"callView")==null&&app.Shell==null,"Escape failed to end call or opened shell");Require(manager.Data.Ai.Messages.Count==2&&manager.Data.Ai.Messages[0].Text=="Hello there","Completed call transcript not retained in chat");Console.WriteLine("PASS voice UI: Escape releases session and returns to transcript without opening Settings");
            Click(send); // Transcript does not change the empty draft call affordance.
            await Task.Delay(120);call=Field<VoiceCallView>(view,"callView");var currentOrb=Field<CallOrb>(call,"orb");widget.Hide();await Task.Delay(100);Require(!currentOrb.IsAnimating&&!session!.Active&&!audio!.Recording,"Hidden call kept rendering or microphone capture active");widget.Show();await Task.Delay(100);call.Leave();await Task.Delay(200);
            using(var speaker=new PcmSpeaker(widget.Dispatcher)){speaker.Open();speaker.Write(new byte[4800]);await Task.Delay(250);Require(!speaker.Playing&&speaker.PlayedBytes>=4800,"Native PCM playback position did not advance");speaker.Clear();Require(speaker.PlayedBytes==0,"Native playback reset retained stale position");speaker.Write(new byte[2400]);await Task.Delay(200);Require(!speaker.Playing,"Native playback failed after interruption reset");}Console.WriteLine("PASS native audio: silent PCM output drains, reports playback position and restarts after reset; microphone never opened by this check");
            var settings=new VoiceCallSettingsView(manager,_=>{});Require(All<ComboBox>(settings).Count()==3&&All<CheckBox>(settings).Any(),"Voice settings lack provider voices, language or action control");var language=All<ComboBox>(settings).Single(b=>AutomationProperties.GetName(b)=="Conversation language");Require(language.Items.Cast<string>().SequenceEqual(new[]{"Ukrainian","English","Auto"}),"Removed language still appears in UI");var confirm=All<CheckBox>(settings).Single(b=>(string?)b.Content=="Ask before browser and app control");Require(confirm.IsChecked==false,"Default confirmation toggle is on");confirm.IsChecked=true;language.SelectedIndex=0;Click(All<Button>(settings).Single(b=>(string?)b.Content=="Save voice preferences"));var saved=manager.Store.Load();Require(saved.AiAskBeforeControl&&saved.VoiceCall.Language=="uk","Control/language preferences did not persist");confirm.IsChecked=false;language.SelectedIndex=2;Click(All<Button>(settings).Single(b=>(string?)b.Content=="Save voice preferences"));Require(!manager.Store.Load().AiAskBeforeControl&&manager.Store.Load().VoiceCall.Language=="auto","Direct control preference did not persist");
            var settingsHost=new Window{Content=new Border{Padding=new Thickness(24),Child=settings},Background=Ui.Brush("Background"),Foreground=Ui.Brush("Text"),Width=640,Height=820,Title="Voice control settings fixture"};settingsHost.Show();settingsHost.UpdateLayout();Snapshot(settingsHost,Path.Combine(root,"voice-control-settings.png"));settingsHost.Close();orb.MotionEnabled=false;orb.Active=true;Require(!orb.IsAnimating,"Reduced motion retained orb rendering");Console.WriteLine("PASS voice UI: provider voice/language/action settings and reduced-motion rendering");Console.WriteLine("Voice call UI artifacts: "+root);
        }catch(Exception e){failure=e;}finally{widget.CloseOwned();manager.Dispose();app.Shutdown();}};app.Run();if(failure!=null)System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(failure).Throw();
    }
    static IEnumerable<T> All<T>(DependencyObject root)where T:DependencyObject{if(root is T target)yield return target;for(var i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var item in All<T>(VisualTreeHelper.GetChild(root,i)))yield return item;}
    static void Snapshot(Window window,string path)=>Snapshot((FrameworkElement)window,path);
    static void Snapshot(FrameworkElement element,string path){element.UpdateLayout();var image=new RenderTargetBitmap(Math.Max(1,(int)element.ActualWidth),Math.Max(1,(int)element.ActualHeight),96,96,PixelFormats.Pbgra32);image.Render(element);var surface=new DrawingVisual();using(var dc=surface.RenderOpen()){dc.DrawRectangle(new SolidColorBrush(Color.FromRgb(27,33,45)),null,new Rect(0,0,image.PixelWidth,image.PixelHeight));dc.DrawImage(image,new Rect(0,0,image.PixelWidth,image.PixelHeight));}var opaque=new RenderTargetBitmap(image.PixelWidth,image.PixelHeight,96,96,PixelFormats.Pbgra32);opaque.Render(surface);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(opaque));using var file=File.Create(path);encoder.Save(file);}
}
